addon='''<dialog class="overlay" id="editor"><div class="overlayhead"><div><strong id="editName">Origins</strong><span style="color:#777;font-size:12px;margin-left:15px">Live preview</span></div><button class="pill" id="closeEditor" aria-label="Close preview">Done ✕</button></div></dialog>
<script>
const editor=document.querySelector('#editor'),workspace=document.querySelector('.workspace');editor.append(workspace);document.querySelector('main').insertAdjacentHTML('afterbegin','');document.querySelector('h1').textContent='A story beneath the surface.';document.querySelector('main > p').textContent='Tiny tears. A growing reveal. One simple control.';document.querySelector('.sectionhead h2').textContent='Choose your reveal';document.querySelector('.sectionhead span').textContent='Hover to watch · Tap to make it yours';document.querySelector('.sectionhead').insertAdjacentHTML('beforebegin','<div class="launch"><button class="primary" id="openEditor">Preview & customize →</button><span>No layers to untangle. Just move the slider.</span></div>');document.querySelector('.footer').textContent='Hover for the full sequence. Tap any card for a larger preview and simple controls.';
const inspector=document.querySelector('.inspector'),advanced=document.createElement('details');advanced.innerHTML='<summary>More options · eye strip & portrait</summary>';while(inspector.firstChild)advanced.append(inspector.firstChild);inspector.append(advanced);const simple=document.createElement('div');simple.innerHTML='<small>MAKE IT YOURS</small><h2 class="easyTitle" style="margin-top:15px">How fast should it spread?</h2><p class="stepNote">Little tears open near the nose, grow together, then reveal the next picture.</p><label for="spreadSpeed">Spread speed <strong id="speedName" style="float:right;color:#c7b3f1">Natural</strong></label><input class="easySpeed" id="spreadSpeed" type="range" min="1" max="100" value="55"><div class="speedEnds"><span>Slower</span><span>Faster</span></div><button class="primary easyReplay" id="watchTear">↻ Watch the reveal</button><p class="stepNote" id="speedHelp">About 5.6 seconds to spread.</p><label for="nextPicture">Next picture</label><button class="pill" id="replacePicture" style="width:100%">Choose a picture…</button><input id="nextPicture" type="file" accept="image/*" hidden><p class="sub">Your picture stays in this browser.</p>';inspector.prepend(simple);
advanced.querySelector('h2').parentElement.style.display='none';advanced.querySelector('#duration').closest('div').querySelector('label:last-of-type').style.display='none';document.querySelector('#duration').parentElement.style.display='none';document.querySelector('#status').style.display='none';document.querySelector('.hint').style.display='none';
let revealSeconds=5.6,speed=55;try{speed=+localStorage.getItem('tearSpeed')||55}catch{};const revealImage=new Image();revealImage.src='assets/reveal.png';let uploadUrl;const oldFrame=frame;const noise=(a,b)=>{const v=Math.sin(a*127.1+b*311.7)*43758.5453;return v-Math.floor(v)};
function tearPath(ctx,cx,cy,rx,ry,seed){ctx.beginPath();for(let i=0;i<=220;i++){let a=i/220*Math.PI*2,r=1+.09*Math.sin(a*19+seed)+.055*Math.sin(a*53+seed*3)+.035*Math.sin(a*91);let x=cx+Math.cos(a)*rx*r,y=cy+Math.sin(a)*ry*r;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.fill()}
frame=function(el,p){const secs=p*settings.duration;oldFrame(el,Math.min(1,secs/8));el.style.setProperty('--close',1+ease((secs-4.2)/3.4)*.72);let canvas=el.querySelector('canvas');if(!canvas){canvas=document.createElement('canvas');canvas.className='tearCanvas';canvas.width=960;canvas.height=540;el.append(canvas)}const ctx=canvas.getContext('2d'),q=clamp((secs-8)/revealSeconds);ctx.clearRect(0,0,960,540);if(q<=0||!revealImage.complete||!revealImage.naturalWidth)return;const iw=revealImage.naturalWidth,ih=revealImage.naturalHeight,k=Math.max(960/iw,540/ih),zoom=1+.1*q;ctx.save();ctx.translate(480,270);ctx.scale(zoom,zoom);ctx.drawImage(revealImage,-iw*k/2,-ih*k/2,iw*k,ih*k);ctx.restore();ctx.globalCompositeOperation='destination-in';const mask=document.createElement('canvas');mask.width=960;mask.height=540;const m=mask.getContext('2d');m.fillStyle='#fff';const growth=Math.pow(q,1.45);for(let n=0;n<7;n++){const x=480+(noise(n,1)-.5)*58,y=268+(noise(n,2)-.5)*45;const start=n*.013,local=clamp((q-start)/(1-start));if(local<=0)continue;const r=2+Math.pow(local,1.48)*760;tearPath(m,x,y,r*(.86+noise(n,3)*.24),r*(.58+noise(n,4)*.18),n+1)}for(let n=0;n<90;n++){const a=noise(n,11)*Math.PI*2,rr=2+growth*760;let x=480+Math.cos(a)*rr*(.86+noise(n,15)*.13),y=268+Math.sin(a)*rr*(.6+noise(n,14)*.1);tearPath(m,x,y,1+q*noise(n,16)*13,1+q*noise(n,17)*10,n)}if(q>.97){m.globalAlpha=ease((q-.97)/.03);m.fillRect(0,0,960,540)}ctx.drawImage(mask,0,0);ctx.globalCompositeOperation='source-over'};
function setSpeed(v){speed=+v;revealSeconds=10-speed*.08;settings.duration=8+revealSeconds;document.querySelector('#speedName').textContent=speed<30?'Slow':speed>75?'Fast':'Natural';document.querySelector('#speedHelp').textContent='About '+revealSeconds.toFixed(1)+' seconds to spread.';localStorage.setItem('tearSpeed',speed)}document.querySelector('#spreadSpeed').value=speed;setSpeed(speed);document.querySelector('#spreadSpeed').oninput=e=>{setSpeed(e.target.value);t=8/settings.duration;playing=true;document.querySelector('#play').textContent='Ⅱ'};
function openEditor(){if(!editor.open)editor.showModal();document.querySelector('#editName').textContent=variants[selected][0];playing=true;document.querySelector('#play').textContent='Ⅱ'}document.querySelector('#openEditor').onclick=()=>{t=0;openEditor()};document.querySelectorAll('.card').forEach(c=>c.addEventListener('click',openEditor));document.querySelector('#watchTear').onclick=()=>{t=7.5/settings.duration;playing=true;document.querySelector('#play').textContent='Ⅱ'};document.querySelector('#closeEditor').onclick=()=>editor.close();editor.addEventListener('close',()=>{playing=false;document.querySelector('#play').textContent='▶'});editor.addEventListener('click',e=>{if(e.target===editor)editor.close()});document.querySelector('#replacePicture').onclick=()=>document.querySelector('#nextPicture').click();document.querySelector('#nextPicture').onchange=e=>{const file=e.target.files[0];if(!file)return;if(uploadUrl)URL.revokeObjectURL(uploadUrl);uploadUrl=URL.createObjectURL(file);revealImage.src=uploadUrl;revealImage.onload=()=>{t=8/settings.duration;playing=true}};document.querySelector('#reset').addEventListener('click',()=>{document.querySelector('#spreadSpeed').value=55;setSpeed(55)});Object.keys(defaults).forEach(k=>document.querySelector('#'+k).addEventListener('input',()=>setSpeed(speed)));document.querySelectorAll('.card').forEach(c=>frame(c.querySelector('.scene'),.83));
</script>'''
s=s.replace('</html>',addon+'</html>');open(p,'w').write(s)
